/**
 * BIG5-GJ v1.0 — Clave de calificación
 * GastroJobs / The Hap&D Co.
 * 
 * @param {number[]} respuestas Array de 60 valores (1-5), en orden del ítem 1 al 60.
 * @returns {Object} Puntajes por dimensión en escala 0-100 + veredicto por corte.
 */
function calificarBIG5GJ(respuestas) {

  if (!respuestas || respuestas.length !== 60) {
    throw new Error('Se requieren exactamente 60 respuestas.');
  }

  // Items inversos (base-1, posición real en array = num-1)
  const INVERSOS = [2,7,9,10,11,19,20,22,27,29,32,37,40,42,44,45,52,53,55,56];

  // Items por dimensión (base-1)
  const DIMENSIONES = {
    R: [1,7,13,19,25,31,37,43,49,55],
    E: [2,8,14,20,26,32,38,44,50,56],
    X: [3,9,15,21,27,33,39,45,51,57],
    A: [4,10,16,22,28,34,40,46,52,58],
    O: [5,11,17,23,29,35,41,47,53,59],
    L: [6,12,18,24,30,36,42,48,54,60]
  };

  // Criterios de corte
  const CORTES = {
    R: { PASA: 65, ALERTA: 40 },
    E: { PASA: 60, ALERTA: 40 },
    X: { PASA: 50, ALERTA: 30 },
    A: { PASA: 55, ALERTA: 35 },
    O: { PASA: 45, ALERTA: 30 },
    L: { ALERTA: 70, MUY_ELEVADA: 85 }
  };

  // 1. Aplicar inversión
  const puntajes = respuestas.map((val, idx) => {
    const numItem = idx + 1;
    return INVERSOS.includes(numItem) ? (6 - val) : val;
  });

  // 2. Calcular suma bruta y convertir a escala 0-100
  const resultados = {};
  for (const [dim, items] of Object.entries(DIMENSIONES)) {
    const sumaBruta = items.reduce((acc, num) => acc + puntajes[num - 1], 0);
    const puntaje100 = sumaBruta * 2; // rango 10-50 → 20-100
    resultados[dim] = { bruto: sumaBruta, puntaje: puntaje100 };
  }

  // 3. Aplicar criterios de corte por dimensión
  const veredictos = {};
  for (const dim of ['R','E','X','A','O']) {
    const p = resultados[dim].puntaje;
    const c = CORTES[dim];
    if (p >= c.PASA) veredictos[dim] = 'PASA';
    else if (p >= c.ALERTA) veredictos[dim] = 'ALERTA';
    else veredictos[dim] = 'DESCARTE';
  }

  // 4. Evaluar Escala L
  const pL = resultados['L'].puntaje;
  if (pL >= CORTES.L.MUY_ELEVADA) {
    veredictos['L'] = 'MUY_ELEVADA — Perfil poco confiable';
  } else if (pL >= CORTES.L.ALERTA) {
    veredictos['L'] = 'ALERTA — Profundizar en entrevista';
  } else {
    veredictos['L'] = 'NORMAL';
  }

  // 5. Veredicto global
  const hayDescarte = ['R','E','X','A','O'].some(d => veredictos[d] === 'DESCARTE');
  const hayAlerta   = ['R','E','X','A','O'].some(d => veredictos[d] === 'ALERTA');
  const perfilConfiable = pL < CORTES.L.MUY_ELEVADA;

  let veredictoGlobal;
  if (!perfilConfiable) {
    veredictoGlobal = 'PERFIL NO CONFIABLE — Escala L muy elevada';
  } else if (hayDescarte) {
    veredictoGlobal = 'NO PASA';
  } else if (hayAlerta) {
    veredictoGlobal = 'PASA CON ALERTAS';
  } else {
    veredictoGlobal = 'PASA';
  }

  return {
    instrumento: 'BIG5-GJ v1.0',
    puntajes: {
      R: resultados.R.puntaje,
      E: resultados.E.puntaje,
      X: resultados.X.puntaje,
      A: resultados.A.puntaje,
      O: resultados.O.puntaje,
      L: resultados.L.puntaje
    },
    veredictos: veredictos,
    veredicto_global: veredictoGlobal
  };
}

/**
 * Ejemplo de uso desde hoja de cálculo:
 * =calificarBIG5GJDesdeRango(B2:BI2)
 */
function calificarBIG5GJDesdeRango(rangoRespuestas) {
  const respuestas = Array.isArray(rangoRespuestas[0])
    ? rangoRespuestas[0]
    : rangoRespuestas;
  const resultado = calificarBIG5GJ(respuestas.map(Number));
  // Para usar en celda — regresa string formateado
  return JSON.stringify(resultado, null, 2);
}
